import {ageQuestions} from './course-ages.js';
import {topicId,topicContent} from './course-content.js';
import {complete,recordAttempt} from './engine.js';
export function canOpenTopic(state,subject,index){return Number.isInteger(index)&&index>=0&&index<6&&(index===0||!!state.completed[topicId(state.age,subject,index-1,'apply')]);}
export function recordFor(state,subject,index){const id=topicId(state.age,subject,index,'record');state.course??={};return state.course[id]??={stage:0,correct:[],hints:[],attempts:{},level:0,project:{prediction:'',evidence:'',conclusion:''}};}
export function answerQuestion(state,subject,index,qIndex,value,hinted=false){if(!canOpenTopic(state,subject,index))throw Error('Complete the previous topic first.');const t=topicContent(subject,index,state.age),r=recordFor(state,subject,index);if(r.stage<2)throw Error('Study and explore the model before practice.');if(qIndex>0&&!r.correct.includes(0))throw Error('Complete the guided check first.');const q=ageQuestions(t)[qIndex];if(!q)throw Error('Unknown question');const ok=Number.isFinite(value)&&Math.abs(value-q.answer)<.011;const id=topicId(state.age,subject,index,'q'+qIndex);recordAttempt(state,id,ok,hinted);r.attempts[qIndex]=(r.attempts[qIndex]||0)+1;if(hinted&&!r.hints.includes(qIndex))r.hints.push(qIndex);if(ok&&!r.correct.includes(qIndex))r.correct.push(qIndex);if(ok&&qIndex===0)complete(state,topicId(state.age,subject,index,'learn'),r.hints.length>0);r.level=r.correct.length>=2&&r.hints.length===0&&Object.values(r.attempts).every(n=>n===1)?2:r.correct.length?1:0;let awarded=false;if(r.correct.length===3)awarded=complete(state,topicId(state.age,subject,index,'apply'),r.hints.length>0);return {ok,reason:q.reason,awarded,mastered:r.correct.length===3,recommendation:ok?(r.level===2?'Try the extension and explain the assumptions.':'Continue to the next challenge.'):r.attempts[qIndex]>=2?'Return to the worked example, then use a hint and retry.':'Compare your steps with the model before retrying.'};}
export function nextQuestion(record){return [0,1,2].find(i=>!record.correct.includes(i))??2;}
